   "start": "import csv, io\nfrom datetime import date, datetime, timedelta\nimport veri\n\nSUTUNLAR = [\"event_id\", \"user_id\", \"event_type\", \"event_time\", \"device\"]\n\ndef ham_partiler():\n    \"\"\"Gerçek web_events satırlarını günlük CSV partilerine böler ve belgelenmiş bozulmaları ekler.\"\"\"\n    gunler = {}\n    for r in veri.kayitlar(\"anadolu_market\", \"web_events\"):\n        s = {k: str(r[k]) for k in SUTUNLAR}\n        n = r[\"event_id\"]\n        z = s[\"event_time\"]\n        parti = z[:10]\n        if n % 101 == 0:   # düzeltilebilir: harf ve boşluk\n            s[\"event_type\"] = \" \" + s[\"event_type\"].upper() + \" \"\n        if n % 103 == 0:   # düzeltilebilir: başka tarih biçimi\n            s[\"event_time\"] = z[8:10] + \".\" + z[5:7] + \".\" + z[:4] + z[10:]\n        if n % 211 == 0:   # reddedilir: kullanıcı yok\n            s[\"user_id\"] = \"\"\n        if n % 223 == 0:   # reddedilir: tanınmayan olay\n            s[\"event_type\"] = \"sayfa_gorunum\"\n        if n % 227 == 0:   # reddedilir: imkânsız tarih\n            s[\"event_time\"] = z[:5] + \"13\" + z[7:]\n        if n % 229 == 0:   # reddedilir: tanınmayan cihaz\n            s[\"device\"] = \"buzdolabi\"\n        if n % 59 == 0:    # geç gelen satır: iki gün sonraki partide\n            parti = (date.fromisoformat(parti) + timedelta(days=2)).isoformat()\n        gunler.setdefault(parti, []).append(s)\n    partiler = {}\n    for parti in sorted(gunler):\n        f = io.StringIO()\n        y = csv.DictWriter(f, SUTUNLAR, lineterminator=\"\\n\")\n        y.writeheader()\n        y.writerows(gunler[parti])\n        partiler[parti] = f.getvalue()\n    return partiler\n\n# Senin kodun\nADIMLAR = {\"visit\": 1, \"product_view\": 2, \"add_to_cart\": 3, \"checkout\": 4, \"purchase\": 5}\nCIHAZLAR = {\"mobile\", \"desktop\"}\n\ndef satir_dogrula(ham):\n    # (temiz_sozluk, None) ya da (None, neden) döndür\n    pass\n",
   "sol": "import csv, io\nfrom datetime import date, datetime, timedelta\nimport veri\n\nSUTUNLAR = [\"event_id\", \"user_id\", \"event_type\", \"event_time\", \"device\"]\n\ndef ham_partiler():\n    \"\"\"Gerçek web_events satırlarını günlük CSV partilerine böler ve belgelenmiş bozulmaları ekler.\"\"\"\n    gunler = {}\n    for r in veri.kayitlar(\"anadolu_market\", \"web_events\"):\n        s = {k: str(r[k]) for k in SUTUNLAR}\n        n = r[\"event_id\"]\n        z = s[\"event_time\"]\n        parti = z[:10]\n        if n % 101 == 0:   # düzeltilebilir: harf ve boşluk\n            s[\"event_type\"] = \" \" + s[\"event_type\"].upper() + \" \"\n        if n % 103 == 0:   # düzeltilebilir: başka tarih biçimi\n            s[\"event_time\"] = z[8:10] + \".\" + z[5:7] + \".\" + z[:4] + z[10:]\n        if n % 211 == 0:   # reddedilir: kullanıcı yok\n            s[\"user_id\"] = \"\"\n        if n % 223 == 0:   # reddedilir: tanınmayan olay\n            s[\"event_type\"] = \"sayfa_gorunum\"\n        if n % 227 == 0:   # reddedilir: imkânsız tarih\n            s[\"event_time\"] = z[:5] + \"13\" + z[7:]\n        if n % 229 == 0:   # reddedilir: tanınmayan cihaz\n            s[\"device\"] = \"buzdolabi\"\n        if n % 59 == 0:    # geç gelen satır: iki gün sonraki partide\n            parti = (date.fromisoformat(parti) + timedelta(days=2)).isoformat()\n        gunler.setdefault(parti, []).append(s)\n    partiler = {}\n    for parti in sorted(gunler):\n        f = io.StringIO()\n        y = csv.DictWriter(f, SUTUNLAR, lineterminator=\"\\n\")\n        y.writeheader()\n        y.writerows(gunler[parti])\n        partiler[parti] = f.getvalue()\n    return partiler\n\nADIMLAR = {\"visit\": 1, \"product_view\": 2, \"add_to_cart\": 3, \"checkout\": 4, \"purchase\": 5}\nCIHAZLAR = {\"mobile\", \"desktop\"}\n\ndef satir_dogrula(ham):\n    kul = (ham.get(\"user_id\") or \"\").strip()\n    if not kul.isdigit() or int(kul) <= 0:\n        return None, \"kullanici_gecersiz\"\n    tur = (ham.get(\"event_type\") or \"\").strip().lower()\n    if tur not in ADIMLAR:\n        return None, \"tur_gecersiz\"\n    metin = (ham.get(\"event_time\") or \"\").strip()\n    zaman = None\n    for bicim in (\"%Y-%m-%d %H:%M:%S\", \"%d.%m.%Y %H:%M:%S\"):\n        try:\n            zaman = datetime.strptime(metin, bicim)\n            break\n        except ValueError:\n            pass\n    if zaman is None:\n        return None, \"zaman_gecersiz\"\n    cihaz = (ham.get(\"device\") or \"\").strip().lower()\n    if cihaz not in CIHAZLAR:\n        return None, \"cihaz_gecersiz\"\n    return {\"kaynak_id\": int(ham[\"event_id\"]), \"kullanici\": int(kul), \"tur\": tur,\n            \"zaman\": zaman.strftime(\"%Y-%m-%d %H:%M:%S\"), \"cihaz\": cihaz}, None\n",
   "tests": "_iyi = {\"event_id\": \"7\", \"user_id\": \" 12 \", \"event_type\": \" VISIT \", \"event_time\": \"21.10.2024 03:11:25\", \"device\": \"Mobile \"}\n_s = satir_dogrula(_iyi)\nassert isinstance(_s, tuple) and len(_s) == 2, \"(temiz, neden) demeti döndürmelisin\"\nassert _s == ({\"kaynak_id\": 7, \"kullanici\": 12, \"tur\": \"visit\", \"zaman\": \"2024-10-21 03:11:25\", \"cihaz\": \"mobile\"}, None), \"Temiz satır yanlış: \" + repr(_s)\n_t = dict(_iyi, event_time=\"2024-10-21 03:11:25\")\nassert satir_dogrula(dict(_t, user_id=\"\"))[1] == \"kullanici_gecersiz\", \"Boş kullanıcı reddedilmeli\"\nassert satir_dogrula(dict(_t, user_id=\"-3\"))[1] == \"kullanici_gecersiz\", \"Negatif kullanıcı reddedilmeli\"\nassert satir_dogrula(dict(_t, user_id=\"0\"))[1] == \"kullanici_gecersiz\", \"0 pozitif değil\"\nassert satir_dogrula(dict(_t, event_type=\"sayfa\"))[1] == \"tur_gecersiz\"\nassert satir_dogrula(dict(_t, event_time=\"2024-13-21 03:11:25\"))[1] == \"zaman_gecersiz\", \"13. ay gerçek bir tarih değil\"\nassert satir_dogrula(dict(_t, event_time=\"31.02.2024 03:11:25\"))[1] == \"zaman_gecersiz\", \"31 Şubat gerçek bir tarih değil\"\nassert satir_dogrula(dict(_t, device=\"buzdolabi\"))[1] == \"cihaz_gecersiz\"\nassert satir_dogrula(dict(_t, user_id=\"\", event_type=\"x\"))[1] == \"kullanici_gecersiz\", \"Kurallar sırayla denetlenmeli\"\nfrom collections import Counter\n_c = Counter()\nfor _p, _m in ham_partiler().items():\n    for _r in csv.DictReader(io.StringIO(_m)):\n        _c[satir_dogrula(_r)[1]] += 1\nassert _c == {None: 2770, 'kullanici_gecersiz': 13, 'zaman_gecersiz': 12, 'tur_gecersiz': 12, 'cihaz_gecersiz': 12}, \"Gerçek veride sayılar farklı: \" + repr(dict(_c))\n",
